 ("Chunk", "A piece of a document, sized for embedding and retrieval.", 5),
 ("Chunk overlap", "Repeated text between neighbouring chunks, so answers across a boundary are not lost.", 6),
 ("Context window", "The maximum number of tokens a model can consider at once.", 3),
 ("Cosine similarity", "A score from -1 to 1 measuring how aligned two vectors are; higher means closer meaning.", 7),
 ("Embedding", "A list of numbers that represents the meaning of a text.", 7),
 ("Evaluation (evals)", "Testing an AI system against a fixed set of questions with expected answers or checks.", 13),
 ("Faithfulness", "Whether every claim in an answer is supported by the retrieved context.", 13),
 ("Golden dataset", "A fixed, expert-checked set of test questions and expected answers.", 13),
 ("Groundedness", "Whether an answer is anchored in the provided sources.", 13),
 ("Guardrail", "A check before or after the model that blocks or flags unsafe or unsupported output.", 14),
 ("Hallucination", "A fluent answer that is not supported by facts or sources.", 3),
 ("Human-in-the-loop", "A design where a person reviews or approves model output or actions.", 9),
 ("Hybrid search", "Combining keyword search and vector search, then merging the results.", 7),
 ("Inference", "Running a trained model to produce an output from an input.", 3),
 ("JSON", "A text format for structured data: objects with keys and values.", 2),
 ("LLM", "Large language model: a neural network trained on large text data to predict and generate text.", 3),
 ("LLMOps", "Operations for LLM systems: logging, monitoring, versioning, evaluation and rollback.", 16),
 ("MCP (Model Context Protocol)", "An open standard for AI apps to discover and use tools, resources and prompts from servers.", 11),
 ("North Star metric", "The single metric that best predicts long-term value of a product.", 22),
 ("Prompt injection", "Hidden instructions in input or retrieved text that try to override the system's rules.", 14),
 ("RAG", "Retrieval-augmented generation: retrieve relevant text first, then answer from it.", 5),
 ("Rate limit", "A provider's cap on requests or tokens per time period.", 2),
 ("Reranker", "A model that re-scores retrieved chunks to put the most relevant first.", 7),
 ("Retrieval recall", "The share of relevant chunks that the retriever found.", 13),
 ("Retrieval precision", "The share of retrieved chunks that were relevant.", 13),
 ("Structured output", "Model output in a fixed format (for example JSON with named keys), validated by code.", 4),
 ("System prompt", "Standing instructions that set the model's role and rules.", 4),
 ("Temperature", "A setting that controls how random the next-token choice is.", 3),
